// Initialize output with safe defaults
qn_output.mode = QN_FAULT;
qn_output.good = 0;
qn_output.norm_error = 0.0;
qn_output.step_rad = 0.0;
qn_output.normalized.w = 1.0;
qn_output.normalized.x = 0.0;
qn_output.normalized.y = 0.0;
qn_output.normalized.z = 0.0;

// 1. Validate Configuration
int config_valid = 1;
if (!isfinite(qn_config.norm_error_limit) || qn_config.norm_error_limit < 0.0) {
    config_valid = 0;
}
if (!isfinite(qn_config.step_limit_rad) || qn_config.step_limit_rad < 0.0 || qn_config.step_limit_rad > PI) {
    config_valid = 0;
}
if (qn_config.required < 1 || qn_config.required > 20) {
    config_valid = 0;
}

if (!config_valid) {
    qn_state.mode = QN_FAULT;
    qn_state.initialized = 0;
    qn_state.good = 0;
    qn_state.previous.w = 1.0;
    qn_state.previous.x = 0.0;
    qn_state.previous.y = 0.0;
    qn_state.previous.z = 0.0;
    // Output remains FAULT defaults
    return;
}

// 2. Handle Disabled State
if (qn_input.enable == 0) {
    qn_state.mode = QN_OFF;
    qn_state.initialized = 0;
    qn_state.good = 0;
    qn_state.previous.w = 1.0;
    qn_state.previous.x = 0.0;
    qn_state.previous.y = 0.0;
    qn_state.previous.z = 0.0;

    qn_output.mode = QN_OFF;
    qn_output.good = 0;
    qn_output.norm_error = 0.0;
    qn_output.step_rad = 0.0;
    qn_output.normalized.w = 1.0;
    qn_output.normalized.x = 0.0;
    qn_output.normalized.y = 0.0;
    qn_output.normalized.z = 0.0;
    return;
}

// 3. Input Validation
const adcs_quat_t *sample = qn_input.sample;
if (sample == NULL || !isfinite(sample->w) || !isfinite(sample->x) || 
    !isfinite(sample->y) || !isfinite(sample->z)) {
    qn_output.mode = QN_MONITOR;
    qn_output.good = qn_state.good; // Do not update history/good count
    qn_output.norm_error = 0.0;
    qn_output.step_rad = 0.0;
    qn_output.normalized.w = 0.0;
    qn_output.normalized.x = 0.0;
    qn_output.normalized.y = 0.0;
    qn_output.normalized.z = 0.0;
    return;
}

// 4. Normalize and Compute Errors
double raw_norm_sq = sample->w*sample->w + sample->x*sample->x + sample->y*sample->y + sample->z*sample->z;
double raw_norm = sqrt(raw_norm_sq);

// Check for zero vector which cannot be normalized meaningfully for attitude
if (raw_norm <= ADCS_EPS_QUAT) {
    qn_output.mode = QN_MONITOR;
    qn_output.good = qn_state.good;
    qn_output.norm_error = 0.0;
    qn_output.step_rad = 0.0;
    qn_output.normalized.w = 0.0;
    qn_output.normalized.x = 0.0;
    qn_output.normalized.y = 0.0;
    qn_output.normalized.z = 0.0;
    return;
}

adcs_quat_t normalized;
normalized.w = sample->w / raw_norm;
normalized.x = sample->x / raw_norm;
normalized.y = sample->y / raw_norm;
normalized.z = sample->z / raw_norm;

double norm_error = fabs(raw_norm - 1.0);

double step_rad = 0.0;
if (qn_state.initialized) {
    double abs_dot = adcs_quat_abs_dot(&normalized, &qn_state.previous);
    // Clamp due to potential floating point errors
    if (abs_dot > 1.0) abs_dot = 1.0;
    if (abs_dot < -1.0) abs_dot = -1.0; // Should not happen with abs_dot but safe
    step_rad = acos(abs_dot);
}

// 5. Quality Check
int quality_ok = (norm_error <= qn_config.norm_error_limit) && (step_rad <= qn_config.step_limit_rad);

if (!quality_ok) {
    // Violation: Return MONITOR, reset good count, do NOT update history
    qn_state.mode = QN_MONITOR;
    qn_state.good = 0;

    qn_output.mode = QN_MONITOR;
    qn_output.good = 0;
    qn_output.norm_error = norm_error;
    qn_output.step_rad = step_rad;
    qn_output.normalized = normalized;
    return;
}

// 6. Success Path: Increment and Update History
qn_state.good++;
qn_state.previous = normalized;
qn_state.initialized = 1;

// Determine Mode
if (qn_state.good >= qn_config.required) {
    qn_state.mode = QN_READY;
} else {
    qn_state.mode = QN_MONITOR;
}

qn_output.mode = qn_state.mode;
qn_output.good = qn_state.good;
qn_output.norm_error = norm_error;
qn_output.step_rad = step_rad;
qn_output.normalized = normalized;

